function MIRROR_SWAP(h11, h21, h31, h22):
    return (h31, h21, h11, h22)        # involution: swap h11 <-> h31

function EULER_CHAR_KLRY(h11, h21, h31):
    h22 <- 2 * (22 + 2*h11 + 2*h31 - h21)    # KLRY relation
    chi <- 6 * (8 + h11 + h31 - h21)         # F-theory formula
    return (h22, chi)
